<?php
// CLI-only, isolated test database only. Never load site configuration or dispatch outbox.
if (PHP_SAPI !== 'cli') { http_response_code(404); exit; }
$dsn = getenv('CHAOXI_TEST_DSN');
if (!$dsn || strpos($dsn, 'mysql:') !== 0 || preg_match_all('/(?:^|;)\s*dbname\s*=/i', substr($dsn, 6)) !== 1 || !preg_match('/(?:^|;)dbname=chaoxi_wallet_test_[A-Za-z0-9_]+(?:;|$)/', substr($dsn, 6))) throw new RuntimeException('请指定独立的 chaoxi_wallet_test_ 前缀 MySQL 测试库，且仅允许一个 dbname。');
$options = array(PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES=>false);
$pdo = new PDO($dsn, getenv('CHAOXI_TEST_USER'), getenv('CHAOXI_TEST_PASSWORD'), $options);
if (!preg_match('/\Achaoxi_wallet_test_[A-Za-z0-9_]+\z/D', (string)$pdo->query('SELECT DATABASE()')->fetchColumn())) throw new RuntimeException('实际连接库不是独立测试库，拒绝执行迁移。');
$root = dirname(__DIR__);
spl_autoload_register(function($class) use ($root) { foreach (array('/app/Services/', '/app/Core/') as $dir) { $file=$root.$dir.$class.'.php'; if (is_file($file)) { require_once $file; return; } } });
require $root.'/scripts/migrate.php';
function g_assert($value, $message) { if (!$value) throw new RuntimeException($message); }
function g_value($sql, $args=array()) { global $pdo; $s=$pdo->prepare($sql); $s->execute($args); return $s->fetchColumn(); }
function g_exec($sql, $args=array()) { global $pdo; $s=$pdo->prepare($sql); $s->execute($args); }
function g_reject($fn) { try { $fn(); } catch (PDOException $e) { throw $e; } catch (RuntimeException $e) { return; } catch (InvalidArgumentException $e) { return; } throw new RuntimeException('预期业务拒绝但操作成功'); }
if (isset($argv[1]) && $argv[1]==='--worker') {
    try {
        if ($argv[2]==='reserve') (new OrderService($pdo))->create((int)$argv[3],(int)$argv[4],(int)$argv[5],'isolated race','group:'.$argv[6]);
        elseif ($argv[2]==='pay') (new OrderService($pdo))->payWithBalance($argv[3],(int)$argv[4]);
        elseif ($argv[2]==='release') (new GroupService($pdo))->processOrder((int)$argv[3]);
        elseif ($argv[2]==='cancel') (new OrderService($pdo))->cancel($argv[3],'user',(int)$argv[4],'isolated race');
        elseif ($argv[2]==='callback') (new OrderService($pdo))->confirmPaymentSystem($argv[3],'alipay',$argv[5],'{}',(int)$argv[4]);
        else throw new RuntimeException('未知测试操作');
        echo 'OK'; exit(0);
    } catch (Exception $e) { echo 'REJECT: '.$e->getMessage(); exit(2); }
}
function g_parallel($jobs) {
    $running=array(); foreach ($jobs as $job) { $pipes=array(); $process=proc_open(array_merge(array(PHP_BINARY,__FILE__,'--worker'),$job),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('pipe','w')),$pipes); if (!is_resource($process)) throw new RuntimeException('无法启动并发测试'); fclose($pipes[0]); $running[]=array($process,$pipes); }
    $success=0; foreach ($running as $child) { $out=stream_get_contents($child[1][1]); $err=stream_get_contents($child[1][2]); fclose($child[1][1]); fclose($child[1][2]); $exit=proc_close($child[0]); if ($exit===0 && $out==='OK') $success++; elseif ($exit!==2 || strpos($out,'REJECT: ')!==0 || $err!=='') throw new RuntimeException('并发进程异常：'.$out.$err); }
    return $success;
}
$passed=0; $failed=0;
function g_case($name,$fn) { global $pdo,$passed,$failed; try { $fn(); $passed++; echo 'PASS: '.$name.PHP_EOL; } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); $failed++; echo 'FAIL: '.$name.' — '.get_class($e).': '.$e->getMessage().PHP_EOL; } }
run_migrations($pdo,$root); run_migrations($pdo,$root);
$stamp=bin2hex(random_bytes(6)); $now=date('Y-m-d H:i:s');
g_exec('INSERT INTO admin_users(email,password_hash,created_at,updated_at) VALUES(?,"test",?,?)',array('group_admin_'.$stamp.'@example.test',$now,$now)); $aid=(int)$pdo->lastInsertId();
function g_user() { global $pdo,$stamp,$now; g_exec('INSERT INTO users(email,password_hash,display_name,created_at,updated_at) VALUES(?,"test","拼团隔离测试",?,?)',array(bin2hex(random_bytes(6)).$stamp.'@example.test',$now,$now)); return (int)$pdo->lastInsertId(); }
function g_product($price) { global $pdo,$now; g_exec('INSERT INTO products(name,description,traffic,region,duration_days,price_cents,created_at,updated_at) VALUES("拼团隔离套餐","test","1G","test",30,?,?,?)',array($price,$now,$now)); $pid=(int)$pdo->lastInsertId(); g_exec('INSERT INTO product_plans(product_id,name,duration_days,price_cents,created_at,updated_at) VALUES(?,"test",30,?,?,?)',array($pid,$price,$now,$now)); return array($pid,(int)$pdo->lastInsertId()); }
list($pid,$plan)=g_product(1000); list($pid2,$plan2)=g_product(2000);
$orders=new OrderService($pdo); $activity=new ActivityService($pdo); $wallet=new WalletService($pdo); $groups=new GroupService($pdo);
function g_config($enabled=true,$discount=80) { global $activity,$aid,$plan,$plan2; $activity->saveSetting('group',array('status'=>$enabled?'enabled':'disabled','config'=>array('target_members'=>3,'discount_percent'=>$discount,'duration_hours'=>24,'reservation_minutes'=>15,'plan_ids'=>array($plan,$plan2))),$aid); }
function g_fixture($count=3,$second=false) { global $activity,$orders,$pid,$plan,$pid2,$plan2; g_config(); $users=array(); for($i=0;$i<$count;$i++) $users[]=g_user(); $gid=(int)$activity->createGroup($users[0],$plan); foreach(array_slice($users,1) as $u) $activity->joinGroup($gid,$u,$second?$plan2:$plan); return array($gid,$users); }
function g_order($gid,$uid,$second=false) { global $orders,$pid,$plan,$pid2,$plan2; return $orders->create($uid,$second?$pid2:$pid,$second?$plan2:$plan,'isolated group','group:'.$gid); }
function g_fund($uid,$amount=10000) { global $wallet,$aid,$stamp; $wallet->adjust($uid,$amount,'isolated group funding','group_fund_'.$stamp.'_'.$uid.'_'.$amount,$aid); }
function g_expire($gid) { g_exec('UPDATE group_campaigns SET expires_at=DATE_SUB(NOW(),INTERVAL 1 SECOND) WHERE id=?',array($gid)); }
function g_worker() { global $groups; g_assert(method_exists($groups,'runOnce'),'GroupService::runOnce未实现'); return $groups->runOnce(1000); }
function g_payment($no,$uid,$suffix='') { global $orders,$pdo,$now,$stamp; $o=$orders->getForUser($no,$uid); g_exec('INSERT INTO payment_records(order_id,method,gateway_type,gateway_order_no,amount_cents,status,created_at,updated_at) VALUES(?,"epay_alipay","alipay",?, ?,"pending",?,?)',array($o['id'],'group_'.$stamp.'_'.bin2hex(random_bytes(4)).$suffix,$o['total_amount_cents'],$now,$now)); return (int)$pdo->lastInsertId(); }
$activity->saveSetting('referral',array('status'=>'enabled','config'=>array('rate_bps'=>1000,'minimum_withdraw_cents'=>1)),$aid);
g_case('fresh/repeated migrations and worker interface',function() use($groups) { g_assert(method_exists($groups,'runOnce')&&method_exists($groups,'processOrder'),'缺少逐单worker接口'); });
g_case('new group v2 snapshot and join does not reserve',function(){list($g,$us)=g_fixture(5); g_assert((int)g_value('SELECT flow_version FROM group_campaigns WHERE id=?',array($g))===2,'新团不是v2'); g_assert((int)g_value('SELECT reserved_members FROM group_campaigns WHERE id=?',array($g))===0,'页面加入错误占位'); g_assert((int)g_value('SELECT discount_percent_snapshot FROM group_campaigns WHERE id=?',array($g))===80,'未固定折扣快照');});
g_case('concurrent final seat, duplicate reservation and cancelled user exclusion',function() use($pid,$plan,$orders){list($g,$us)=g_fixture(4); g_order($g,$us[0]); g_order($g,$us[1]); g_assert(g_parallel(array(array('reserve',(string)$us[2],(string)$pid,(string)$plan,(string)$g),array('reserve',(string)$us[3],(string)$pid,(string)$plan,(string)$g)))===1,'最后名额必须只有一个胜者'); g_assert((int)g_value('SELECT COUNT(*) FROM group_orders WHERE campaign_id=?',array($g))===3,'超卖名额'); $n=g_order($g,$us[0]); g_assert($n===g_value('SELECT o.order_no FROM orders o JOIN group_orders go ON go.order_id=o.id WHERE go.campaign_id=? AND go.user_id=?',array($g,$us[0])),'重复请求未返回原订单'); $orders->cancel($n,'user',$us[0],'test'); g_reject(function()use($g,$us){g_order($g,$us[0]);});});
g_case('waiting group has no subscription, delivery or referral',function() use($orders,$activity,$aid,$wallet,$now){list($g,$us)=g_fixture();$ref=g_user();g_exec('INSERT INTO referral_relations(referrer_user_id,user_id,status,created_at,updated_at) VALUES(?, ?,"active",?,?)',array($ref,$us[0],$now,$now)); $n=g_order($g,$us[0]);g_fund($us[0]);$orders->payWithBalance($n,$us[0]);$o=$orders->getForUser($n,$us[0]);g_assert($o['status']==='paid_waiting_group'&&$o['temporary_subscription_url']===''&&$o['temporary_subscription_status']==='none','待成团错误交付');g_assert((int)g_value('SELECT COUNT(*) FROM referral_commissions WHERE order_id=?',array($o['id']))===0&&$wallet->balance($ref)===0,'待成团错误返佣');g_reject(function()use($orders,$n,$aid){$orders->deliver($n,$aid,array('subscription'=>'https://example.test/sub','duration_preset'=>'1m'),array());});});
