g_case('expired balance refund actual discounted amount once, unpaid cancelled',function() use($orders,$wallet){list($g,$us)=g_fixture();$n=g_order($g,$us[0]);$unpaid=g_order($g,$us[1]);g_fund($us[0]);$before=$wallet->balance($us[0]);$orders->payWithBalance($n,$us[0]);g_assert($wallet->balance($us[0])===$before-800,'不是折后实际扣款');g_expire($g);g_worker();g_worker();g_assert($wallet->balance($us[0])===$before,'余额退款不是原路且仅一次');g_assert($orders->getForUser($n,$us[0])['status']==='refunded'&&$orders->getForUser($unpaid,$us[1])['status']==='cancelled','到期订单终态错误');});
g_case('wallet capacity failure remains pending and retry refunds once',function() use($orders,$wallet,$aid,$groups,$stamp){list($g,$us)=g_fixture();$u=$us[0];$n=g_order($g,$u);g_fund($u);$orders->payWithBalance($n,$u);$top=WalletService::MAX_BALANCE_CENTS-$wallet->balance($u);$wallet->adjust($u,$top,'test cap','group_cap_'.$stamp.$u,$aid);g_expire($g);g_worker();$r=(int)g_value('SELECT id FROM group_payment_refunds WHERE order_id=? AND status="pending"',array($orders->getForUser($n,$u)['id']));g_assert($r>0&&$wallet->balance($u)===WalletService::MAX_BALANCE_CENTS,'容量不足应保留待处理退款');$wallet->adjust($u,-800,'free capacity','group_free_'.$stamp.$u,$aid);$groups->retryRefund($r,$aid);g_worker();g_worker();g_assert($wallet->balance($u)===WalletService::MAX_BALANCE_CENTS&&g_value('SELECT status FROM group_payment_refunds WHERE id=?',array($r))==='completed','释放容量后退款重试未完成');});
g_case('external failure/manual refund and late duplicate/extra payments',function() use($orders,$wallet,$groups,$aid){list($g,$us)=g_fixture();$u=$us[0];$n=g_order($g,$u);$pay=g_payment($n,$u);$before=$wallet->balance($u);$orders->confirmPaymentSystem($n,'alipay','mock_trade_'.$pay,'{}',$pay);g_expire($g);g_worker();$id=(int)g_value('SELECT id FROM group_payment_refunds WHERE payment_id=? AND channel="external" AND status="pending"',array($pay));g_assert($id>0&&$wallet->balance($u)===$before,'外部付款没有进入人工原渠道退款');g_reject(function()use($orders,$n,$aid){$orders->processRefund($n,$aid,false,'系统失败退款不能驳回');});g_reject(function()use($orders,$n,$aid){$orders->processRefund($n,$aid,true,'外部退款不能伪造');});g_reject(function()use($groups,$id,$aid){$groups->confirmExternalRefund($id,$aid,'');});$groups->confirmExternalRefund($id,$aid,'mock-refund-'.$pay,'isolated receipt');$groups->confirmExternalRefund($id,$aid,'mock-refund-'.$pay);g_assert(g_value('SELECT status FROM group_payment_refunds WHERE id=?',array($id))==='completed','人工退款未登记');list($g2,$us2)=g_fixture();$n2=g_order($g2,$us2[0]);$late=g_payment($n2,$us2[0]);g_expire($g2);g_worker();g_assert(g_value('SELECT status FROM payment_records WHERE id=?',array($late))==='cancelled','到期未关闭待付款记录');g_assert(g_parallel(array(array('callback',$n2,(string)$late,'mock-late-'.$late),array('callback',$n2,(string)$late,'mock-late-'.$late)))===2,'重复晚款回调未持久化');$extra=g_payment($n2,$us2[0],'extra');$orders->confirmPaymentSystem($n2,'alipay','mock-extra-'.$extra,'{}',$extra);g_assert((int)g_value('SELECT COUNT(*) FROM group_payment_refunds WHERE payment_id IN (?,?)',array($late,$extra))===2,'晚款/额外付款没有分别退款记录');g_assert($orders->getForUser($n2,$us2[0])['status']!=='pending_delivery','晚款错误重新交付');});
g_case('cross-product snapshot, activity closure and migration isolation',function()use($orders,$activity,$plan,$plan2,$pid2,$pdo,$root){list($g,$us)=g_fixture(3,true);g_config(true,50);$n=g_order($g,$us[1],true);$o=$orders->getForUser($n,$us[1]);g_assert((int)$o['product_id']===$pid2&&(int)$o['total_amount_cents']===1600,'跨商品或折扣快照漂移');g_config(false);g_reject(function()use($activity,$plan){$activity->createGroup(g_user(),$plan);});g_reject(function()use($activity,$g,$plan){$activity->joinGroup($g,g_user(),$plan);});g_reject(function()use($g,$us){g_order($g,$us[2]);});g_fund($us[1]);$orders->payWithBalance($n,$us[1]);g_assert($orders->getForUser($n,$us[1])['status']==='paid_waiting_group','关闭活动阻止已有快照付款');g_exec('DELETE FROM group_campaign_plans WHERE campaign_id=? AND product_plan_id=?',array($g,$plan));run_migrations($pdo,$root);g_assert((int)g_value('SELECT COUNT(*) FROM group_campaign_plans WHERE campaign_id=?',array($g))===1,'重复迁移扩张允许方案');g_config();});
