class GroupMockPaymentService extends PaymentService { public function settings(){return array('enabled'=>1,'pid'=>'isolated','md5_key'=>'mock-only','alipay_enabled'=>1,'wechat_enabled'=>1,'notify_base_url'=>'https://example.test','gateway_url'=>'https://example.test');} }
g_case('existing payment URL cannot bypass expired reservation',function()use($orders,$pdo){list($g,$us)=g_fixture();$n=g_order($g,$us[0]);$id=g_payment($n,$us[0]);g_exec('UPDATE payment_records SET payment_url="https://example.test/mock" WHERE id=?',array($id));$svc=new GroupMockPaymentService($pdo,array());g_assert($svc->createPayment($n,$us[0],'alipay')['url']==='https://example.test/mock','有效原支付URL未复用');g_exec('UPDATE group_orders SET reserved_until=DATE_SUB(NOW(),INTERVAL 1 SECOND) WHERE order_id=?',array($orders->getForUser($n,$us[0])['id']));g_reject(function()use($svc,$n,$us){$svc->createPayment($n,$us[0],'alipay');});});
g_case('worker fairness past 100 blocked external refunds and capacity retry',function()use($orders,$groups,$wallet,$aid,$stamp){for($i=0;$i<101;$i++){list($g,$us)=g_fixture(1);$n=g_order($g,$us[0]);$p=g_payment($n,$us[0]);$orders->confirmPaymentSystem($n,'alipay','mock-fair-'.$p,'{}',$p);g_expire($g);$groups->processOrder((int)$orders->getForUser($n,$us[0])['id']);}list($g,$us)=g_fixture(1);$u=$us[0];$n=g_order($g,$u);g_fund($u);$orders->payWithBalance($n,$u);$wallet->adjust($u,WalletService::MAX_BALANCE_CENTS-$wallet->balance($u),'fair cap','fair_cap_'.$stamp,$aid);g_expire($g);$groups->processOrder((int)$orders->getForUser($n,$u)['id']);list($success,$members)=g_fixture();foreach($members as $m){$no=g_order($success,$m);g_fund($m);$orders->payWithBalance($no,$m);}for($i=0;$i<12;$i++)$groups->runOnce(1);g_assert((int)g_value('SELECT COUNT(*) FROM group_orders WHERE campaign_id=? AND released_at IS NOT NULL',array($success))===3,'阻塞退款导致正常成功团永久饥饿');});
g_case('ordinary and group create/pay concurrent wallet conservation',function()use($orders,$pid,$plan,$wallet,$now,$stamp,$aid){list($g,$us)=g_fixture(1);$u=$us[0];g_fund($u);$plain=$orders->create($u,$pid,$plan,'ordinary race');$before=$wallet->balance($u);g_assert(g_parallel(array(array('reserve',(string)$u,(string)$pid,(string)$plan,(string)$g),array('pay',$plain,(string)$u)))===2,'普通付款与拼团下单锁环或拒绝');$groupNo=g_value('SELECT o.order_no FROM orders o JOIN group_orders go ON go.order_id=o.id WHERE go.campaign_id=?',array($g));$other=$orders->create($u,$pid,$plan,'ordinary race 2');g_assert(g_parallel(array(array('pay',$groupNo,(string)$u),array('pay',$other,(string)$u)))===2,'普通/拼团付款并发失败');g_assert($wallet->balance($u)===$before-2800,'普通/拼团并发资金不守恒');});
g_case('poison task rollback does not starve healthy worker orders',function()use($dsn,$options,$orders,$wallet,$groups){$ids=array();foreach(array('poison','healthy') as $kind){list($g,$us)=g_fixture();foreach($us as $u){$n=g_order($g,$u);g_fund($u);$orders->payWithBalance($n,$u);if(!isset($ids[$kind]))$ids[$kind]=(int)$orders->getForUser($n,$u)['id'];}}$rp=new GroupPoisonTestPDO($dsn,getenv('CHAOXI_TEST_USER'),getenv('CHAOXI_TEST_PASSWORD'),$options);$rp->poisonOrder=$ids['poison'];$worker=new GroupService($rp);$sawError=false;for($i=0;$i<15;$i++){ $result=$worker->runOnce(1);if(!empty($result['errors']))$sawError=true;}g_assert($sawError&&$rp->failures>0,'未实际触发毒任务异常');g_assert(g_value('SELECT status FROM orders WHERE id=?',array($ids['poison']))==='paid_waiting_group','毒任务失败没有回滚业务状态');g_assert(g_value('SELECT released_at FROM group_orders WHERE order_id=?',array($ids['poison']))===null,'毒任务错误标记已释放');$poisonUser=(int)g_value('SELECT user_id FROM orders WHERE id=?',array($ids['poison']));g_assert($wallet->balance($poisonUser)===9200&&(int)g_value('SELECT COUNT(*) FROM wallet_transactions WHERE order_id=?',array($ids['poison']))===1,'毒任务异常更改资金或重复写账本');g_assert(g_value('SELECT worker_checked_at FROM group_orders WHERE order_id=?',array($ids['poison']))!==null,'毒任务回滚丢失独立调度标记');g_assert(g_value('SELECT status FROM orders WHERE id=?',array($ids['healthy']))==='pending_delivery','异常毒任务永久阻塞健康订单');});
class GroupPoisonTestPDO extends PDO { public $poisonOrder=0; public $failures=0; public function prepare($query,$options=array()){if(strpos($query,'INSERT INTO notifications(')===0){$s=parent::prepare('SELECT status FROM orders WHERE id=?');$s->execute(array($this->poisonOrder));if($s->fetchColumn()==='pending_delivery'){ $this->failures++;throw new RuntimeException('isolated poison notification rollback');}}return parent::prepare($query,$options);} }
